# But let's use a simpler approach: check if removing any 3 vertices disconnects the graph.

from itertools import combinations

def is_connected_after_removal(removed):
    """Check if graph remains connected after removing vertices in `removed` set."""
    remaining = [v for v in range(n) if v not in removed]
    if not remaining:
        return True  # vacuously
    visited = set()
    stack = [remaining[0]]
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        for u in adj[v]:
            if u not in removed and u not in visited:
                stack.append(u)
    return len(visited) == len(remaining)

# Check all subsets of size 3
disconnected_by_3 = False
for removed in combinations(range(n), 3):
    if not is_connected_after_removal(set(removed)):
        disconnected_by_3 = True
        print(f"Graph disconnected by removing: {removed}")
        break

if not disconnected_by_3:
    print("Graph remains connected after removing any 3 vertices.")

# Also check if removing any 4 vertices disconnects
for removed in combinations(range(n), 4):
